WITH RecentWebEvents AS (SELECT * FROM web_events WHERE duration_sec < 209), web_events_stats AS (SELECT DATE_TRUNC('MONTH', event_time) AS event_month, page, COUNT(DISTINCT duration_sec) AS unique_pages FROM RecentWebEvents GROUP BY DATE_TRUNC('MONTH', event_time), page) SELECT event_month, page, unique_pages FROM web_events_stats WHERE unique_pages >= 5 ORDER BY unique_pages, event_month, page LIMIT 10;
